-- Caso anual confirmado por el propietario el 13/10/2026; Sólo contenido editorial.
INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado)
VALUES ('pago-anual-diciembre-bonificado',$texto$Pagar enero a diciembre: diciembre bonificado y un pago de $11,000$texto$,'Cobranza',$texto$Preparar doce mensualidades de un alumno, bonificar diciembre sin beca, validar un único pago completo y comprobar cobertura anual, cuenta, adeudos y comprobante familiar.$texto$,$texto$Alumno, tutor financiero y acceso familiar activos; mismo plantel, institución, concepto de colegiatura y moneda MXN. Inscripciones y ciclos deben cubrir cada mensualidad de enero a diciembre de 2027; pueden ser varias inscripciones compatibles del mismo alumno. No falsear vigencias: un ciclo que termina el 15/06/2027 no cubre julio a diciembre. Cuenta receptora activa y abierta antes del pago, administrador identificado con permisos. Sin beca aplicable, recargos, abonos previos u otro acuerdo sobre estos cargos. Usar datos de ensayo y adaptar año, fechas y plazo si se reproduce después; no transferir dinero real. Para consultar el caso confirmado no repetir registros ni pagos.$texto$,$texto$Enero a diciembre de 2027: 12 originales de $1,000.00 = $12,000.00; Beca $0.00; Diciembre recibe beneficio de $1,000.00 y queda en $0.00; enero a noviembre se pagan con $1,000.00 cada uno. Un pago completo de $11,000.00 y un solo ingreso B + $11,000.00, donde B es el saldo actual antes de validar. Cobertura anual liquidada: 12/12 meses, once pagados y uno bonificado. Caso completo confirmado por el propietario; folio, alumno y saldo absoluto dependen de cada base de datos.$texto$,1,DATE '2026-10-13','CONFIRMADA');

INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN permiso p ON p.codigo=ANY(ARRAY['INSCRIPCION_LEER','TUTOR_LEER','CONCEPTO_COBRO_ADMINISTRAR','CUOTA_ALUMNO_ADMINISTRAR','CARGO_ADMINISTRAR','CONVENIO_PAGO_ADMINISTRAR','PAGO_REGISTRAR','PAGO_LEER','PAGO_VALIDAR','CUENTA_FINANCIERA_LEER']) WHERE g.slug='pago-anual-diciembre-bonificado';

INSERT INTO guia_proceso_paso(guia_id,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
SELECT g.id,v.numero,v.titulo,v.perfil,v.modulo,v.instrucciones,v.ejemplo,v.resultado,v.precaucion,v.ruta FROM guia_proceso g JOIN (VALUES
('pago-anual-diciembre-bonificado',1,$texto$Comprobar alumno, familia y cobertura del año$texto$,$texto$Administración$texto$,$texto$Inscripciones y Tutores$texto$,$texto$1. Entra a Operación escolar → Control escolar → Inscripciones, busca al alumno → Aplicar filtros → Editar; comprueba institución, plantel, ciclo y vigencia. Anota qué inscripción cubre cada mensualidad de enero a diciembre de 2027; 2. Si el año atraviesa ciclos, usa inscripciones compatibles del mismo alumno para sus periodos reales; cada cargo debe quedar dentro de su inscripción y ciclo. No alargues artificialmente una inscripción para ensayar ni uses una cuota fuera de su vigencia. 3. Entra a Operación escolar → Control escolar → Tutores, busca al tutor → Editar → Portal de familias; comprueba cuenta activa y vínculo financiero vigente con el alumno. Si ya existe, no dupliques acceso. 4. Identifica matrícula y tutor. Usa ventana privada u otro navegador para revisar el portal familiar, porque las pestañas normales comparten sesión administrativa.$texto$,$texto$Año cubierto 2027: desde 01/01/2027 hasta 31/12/2027; El ciclo que termina el 15/06/2027 no basta para las doce mensualidades.$texto$,$texto$Contexto académico y familiar identificado sin generar deuda.$texto$,$texto$Año calendario no significa ciclo escolar; no mezclar hermanos, conceptos o planteles para completar doce meses.$texto$,$texto$/admin/catalogos/inscripciones$texto$),
('pago-anual-diciembre-bonificado',2,$texto$Anotar el saldo actual antes del ingreso$texto$,$texto$Administración$texto$,$texto$Cuentas financieras$texto$,$texto$1. Entra a Administración → Finanzas → Cuentas financieras; busca la cuenta receptora del plantel → Aplicar filtros. 2. Anota Saldo actual como B; abre el detalle y comprueba la cuenta, moneda MXN, estado activo y fecha de apertura no posterior al pago. No uses Saldo inicial como referencia si ya hay movimientos. 3. Conserva el nombre de la cuenta y el saldo B para elegir la misma al registrar y validar; no captures un movimiento manual para preparar este ejemplo. 4. Si consultas el caso ya validado, revisa su movimiento y saldo posterior histórico en Pagos recibidos → Ver → Resumen. Otros ingresos posteriores pueden cambiar el saldo actual; no repitas el pago para compararlo.$texto$,$texto$Si B fuera $5,000.00, al validar este pago el saldo posterior sería $16,000.00, sin otros movimientos concurrentes.$texto$,$texto$Cuenta y comparación B + $11,000.00 documentadas.$texto$,$texto$No asumir el saldo de otra computadora: Git no transporta los datos financieros.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$),
('pago-anual-diciembre-bonificado',3,$texto$Configurar el concepto anual sin beca$texto$,$texto$Administración$texto$,$texto$Conceptos de cobro$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Conceptos de cobro; busca el concepto del ensayo. Si ya existe, revisa su configuración sin duplicarlo. 2. Para un ensayo nuevo pulsa Nuevo registro, selecciona institución y captura código ANUAL-2027-TEST, nombre Colegiatura anual de prueba y categoría Colegiatura. Si ese código ya fue usado, elige uno nuevo y conserva el mismo en los pasos siguientes. 3. Activa Permite descuento y Concepto activo; para aislar este caso deja desactivados Permite beca y Permite recargo. No modifiques conceptos operativos compartidos para hacer pruebas. 4. Pulsa Crear concepto y comprueba código y opciones. El precio individual se capturará en Cuotas por alumno, no en este catálogo.$texto$,$texto$Concepto COLEGIATURA; doce importes de $1,000.00, sin beca ni recargos.$texto$,$texto$Concepto preparado para el beneficio anual.$texto$,$texto$Si usas un concepto existente que permite becas, comprueba que ninguna beca aplicable altere estas mensualidades; de lo contrario el resultado no será $11,000.00.$texto$,$texto$/admin/catalogos/conceptos-cobro$texto$),
('pago-anual-diciembre-bonificado',4,$texto$Configurar las doce mensualidades$texto$,$texto$Administración$texto$,$texto$Cuotas por alumno$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Cuotas por alumno → Crear cuota. Selecciona institución, plantel, inscripción compatible y concepto del ensayo. 2. Captura Importe individual 1000.00, Moneda MXN, Cada mes, Primer mes y Último mes del tramo que esa inscripción realmente cubre, y Día límite de pago de cada mes 20; Para una única inscripción que cubra todo el año, el tramo es enero a diciembre de 2027; 3. Selecciona Estado Activa e Incluir en generación automática de cargos; revisa Configuración adicional y la vigencia admitida. Si son varias inscripciones, configura sus tramos por separado, sin duplicar meses ni dejar fuera ninguna mensualidad de enero a diciembre. 4. Pulsa Crear cuota, revisa el resumen del modal y confirma una sola vez por cuota. Si faltan meses completos válidos por las fechas de inscripción, corrige la preparación antes de emitir; no ignores el error ni fuerces fechas.$texto$,$texto$Doce meses únicos, original $1,000.00 cada uno. Fecha límite ilustrativa: día 20 de cada mes.$texto$,$texto$Configuración mensual preparada; todavía no ingresa dinero.$texto$,$texto$Una sola vez no genera doce mensualidades. El plazo del acuerdo anticipado será independiente de estos vencimientos.$texto$,$texto$/admin/cuotas-alumno/nuevo$texto$),
('pago-anual-diciembre-bonificado',5,$texto$Emitir sólo enero a diciembre del ejemplo$texto$,$texto$Administración$texto$,$texto$Adeudos de alumnos → Generar automáticos$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Adeudos de alumnos → Generar automáticos; selecciona institución y contexto, captura Generar hasta 31/12/2027 y pulsa Visualizar cuotas de alumnos por aplicar. 2. Pulsa Desmarcar todos y selecciona exclusivamente los doce meses del alumno y concepto del ejercicio. Revisa cada fecha, original $1,000.00, beca $0.00 y saldo $1,000.00; no selecciones otros ensayos. 3. Pulsa Confirmar y generar adeudos seleccionados, revisa el modal y confirma una sola vez. Si esos cargos ya existen, consulta los emitidos en lugar de intentar generarlos nuevamente. 4. Pulsa Volver a adeudos de alumnos; busca alumno/concepto y fechas del periodo desde 01/01/2027 hasta 31/12/2027 → Aplicar filtros. Verifica doce mensualidades distintas, sin ajustes ni abonos y deuda total $12,000.00 antes del acuerdo.$texto$,$texto$Enero, febrero, marzo, abril, mayo, junio, julio, agosto, septiembre, octubre, noviembre y diciembre: $1,000.00 cada uno.$texto$,$texto$Doce cargos identificados, sin ingreso ni beneficio todavía.$texto$,$texto$Si faltan meses o aparece beca/recargo, detén el ensayo; contar doce filas mezcladas no demuestra cobertura anual.$texto$,$texto$/admin/cargos/generar$texto$),
('pago-anual-diciembre-bonificado',6,$texto$Preparar el acuerdo y bonificar diciembre$texto$,$texto$Administración$texto$,$texto$Convenios de pago → Acuerdos por pago anticipado$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Convenios de pago → Acuerdos por pago anticipado → Nueva propuesta; selecciona institución y Tutor responsable. 2. En Buscar mensualidades de los hijos enfoca para primeras diez opciones o escribe tres caracteres; agrega los doce cargos del alumno/concepto, uno por cada mes de 2027; Comprueba las tarjetas; Quitar sólo cambia la selección y no cancela el adeudo. 3. Selecciona Conservar beca y agregar beneficio, aunque en este caso no hay beca; Beneficio autorizado: Una mensualidad bonificada; Mensualidad que se bonificará: diciembre de 2027; Captura Fecha límite para pagar completo 20/10/2026 como fecha ilustrativa para un ensayo realizado el 13/10/2026, o un plazo vigente compatible con la fecha real del nuevo pago. 4. En Motivo y condiciones autorizadas captura: Se bonifica diciembre de 2027 al pagar completas las doce colegiaturas de enero a diciembre de 2027 antes del plazo autorizado; sin beca adicional. Incluye la fecha límite elegida y pulsa Visualizar acuerdo; espera el desplazamiento al resumen.$texto$,$texto$Doce bases de $1,000.00; diciembre recibe beneficio $1,000.00; Importe completo requerido $11,000.00.$texto$,$texto$Vista previa sin publicar descuentos ni ingresar dinero.$texto$,$texto$Un pago en 2026 puede cubrir 2027; El beneficio requiere pagar y validar el importe completo del acuerdo, no un abono parcial.$texto$,$texto$/admin/convenios-pago/anticipados/nuevo$texto$),
('pago-anual-diciembre-bonificado',7,$texto$Revisar y guardar la propuesta anual$texto$,$texto$Administración$texto$,$texto$Preparar acuerdo → Así quedaría el acuerdo$texto$,$texto$1. En Así quedaría el acuerdo revisa doce filas con periodos dd/MM/yyyy: enero a noviembre, Original $1,000.00, Beca $0.00, Otros ajustes $0.00, Base $1,000.00, Beneficio $0.00 y Pago requerido $1,000.00 por mes. 2. Revisa diciembre: Original $1,000.00, Beca $0.00, Base $1,000.00, Beneficio $1,000.00 y Pago requerido $0.00; Totales Base seleccionada $12,000.00, Beneficio propuesto $1,000.00 y Pago completo requerido $11,000.00 MXN. 3. Pulsa Guardar propuesta; revisa familia, doce meses, diciembre bonificado, plazo y motivo en el modal. Cancelar no guarda; confirma sólo si todo coincide. 4. En el detalle del acuerdo comprueba Propuesta vigente y conserva su folio. Todavía los adeudos mantienen $12,000.00 y la cuenta conserva B; el beneficio no se publica sólo por guardar.$texto$,$texto$12 × $1,000.00 − $1,000.00 = $11,000.00; No son doce abonos ni un ingreso de $12,000.00.$texto$,$texto$Propuesta anual guardada, saldos sin modificar.$texto$,$texto$Si cambias una selección o condición, vuelve a Visualizar acuerdo antes de guardar. No repitas la propuesta ya aplicada del caso confirmado.$texto$,$texto$/admin/convenios-pago/anticipados$texto$),
('pago-anual-diciembre-bonificado',8,$texto$Registrar un pago completo de $11,000$texto$,$texto$Administración$texto$,$texto$Detalle del acuerdo → Registrar pago completo como pendiente$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Convenios de pago → Acuerdos por pago anticipado, busca el folio de la propuesta → Ver → Registrar pago completo como pendiente. Comprueba importe $11,000.00; 2. Selecciona el método realmente recibido y la Cuenta donde se recibió el dinero cuyo saldo anotaste. Captura fecha y hora reales no futuras, dentro del plazo y no anteriores a la apertura de la cuenta, y referencia TEST-ANUAL-2027-11000; 3. Si eliges Transferencia adjunta el comprobante requerido; Tarjeta permite capturar la referencia o autorización, y Efectivo debe usar la cuenta de caja correspondiente. Pulsa Registrar pago completo, revisa el modal de $11,000.00 y confirma una sola vez. 4. Conserva el folio PAG generado y pulsa Ver pago. No captures otro pago por mes; mientras está pendiente no hay ingreso ni descuento publicado.$texto$,$texto$Un folio PAG automático, un pago de $11,000.00 vinculado al acuerdo y a las doce mensualidades.$texto$,$texto$Pago En revisión; cuenta permanece B.$texto$,$texto$El método aquí es una elección para reproducir el proceso; no se atribuye un método específico al caso confirmado. No declares un importe mayor ni registres el pago desde un formulario ordinario desvinculado.$texto$,$texto$/admin/convenios-pago/anticipados$texto$),
('pago-anual-diciembre-bonificado',9,$texto$Revisar el expediente y validar el pago$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Ver → Gestión$texto$,$texto$1. Entra a Administración → Finanzas → Pagos recibidos, busca folio o referencia → Aplicar filtros → Ver. En Resumen comprueba tutor, plantel, método, cuenta e información del acuerdo; Ver acuerdo y mensualidades permite consultar sus condiciones. 2. Abre Distribución → Meses incluidos en este pago: enero a noviembre $1,000.00 cada uno y diciembre $0.00 por bonificación. Cobertura anual debe identificar el año 2027 como pendiente, no como liquidado antes de validar. 3. Abre Gestión → Control administrativo del pago; revisa destino y total $11,000.00; No cambies la cuenta ni declares dinero adicional si lo capturado es correcto. Pulsa Validar y publicar, revisa el modal y confirma una sola vez. 4. Comprueba estado Validado y acuerdo Beneficio aplicado. Si el pago ya está validado, sólo consulta; el acceso de recuperación no puede autorizar movimientos.$texto$,$texto$Una validación publica el beneficio de diciembre y los once abonos, con un único ingreso de $11,000.00.$texto$,$texto$Pago completo validado y descuento anual aplicado.$texto$,$texto$No uses movimientos manuales para compensar una validación rechazada. Revisa fechas, permisos y cuenta si no permite confirmar.$texto$,$texto$/admin/catalogos/pagos$texto$),
('pago-anual-diciembre-bonificado',10,$texto$Comprobar distribución, cobertura y cuenta$texto$,$texto$Administración$texto$,$texto$Pagos recibidos y Cuentas financieras$texto$,$texto$1. En Administración → Finanzas → Pagos recibidos busca el folio → Ver → Distribución. Comprueba las doce mensualidades: once abonos de $1,000.00 y diciembre $0.00 Bonificada, sin abono. El desglose conserva ese mes para explicar lo que cubrió el acuerdo. 2. Abre Cobertura anual, o en Resumen pulsa Año completo 2027: debe mostrar Anual liquidado, 12/12 meses, once meses pagados completos, uno bonificado, beneficio pactado $1,000.00 y abonos vigentes $11,000.00; 3. En Resumen → Movimiento único de ingreso revisa la cuenta destino, importe $11,000.00 y saldo posterior. Entra a Administración → Finanzas → Cuentas financieras y consulta la misma cuenta → Aplicar filtros: saldo actual B + $11,000.00 si no hubo otros movimientos. 4. Conserva folios y evidencia. Diciembre no crea aplicación0 ficticia ni un ingreso adicional; el comprobante es de $11,000.00, no de $12,000.00.$texto$,$texto$Cobertura anual LIQUIDADO de 2027; banco B + $11,000.00 una sola vez.$texto$,$texto$Desglose de doce meses y dinero recibido coherentes.$texto$,$texto$Una devolución que reabre deuda puede cambiar la clasificación anual; este ensayo no incluye devolución o cancelación.$texto$,$texto$/admin/catalogos/pagos$texto$),
('pago-anual-diciembre-bonificado',11,$texto$Comprobar los adeudos y el comprobante familiar$texto$,$texto$Administración y tutor$texto$,$texto$Adeudos de alumnos y Portal familiar$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Adeudos de alumnos, busca alumno/concepto y periodo de 2027 → Todos o Liquidado → Aplicar filtros. Abre Ver de enero a noviembre: cada uno tiene original $1,000.00, abonado $1,000.00 y saldo $0.00; 2. Abre Ver de diciembre → Resumen e Historial: original $1,000.00, descuento del acuerdo $1,000.00, sin abono monetario y saldo $0.00; Las doce mensualidades quedan liquidadas, pero sólo once recibieron dinero. 3. En ventana privada entra a /familias como tutor, selecciona el hijo → Tus pagos: no debe aparecer deuda por esas doce mensualidades. Otras deudas de ese alumno no forman parte del ejemplo y pueden seguir visibles. 4. En el historial de pagos del alumno localiza el folio validado → Comprobante; comprueba PDF de $11,000.00 abierto en otra pestaña, sin descarga automática. El propietario confirmó ingreso, doce saldos cero, cobertura liquidada y comprobante familiar; no repitas el pago.$texto$,$texto$Enero–noviembre: pagado $1,000.00 y saldo $0.00 por mes. Diciembre: beneficio $1,000.00, abono $0.00 y saldo $0.00.$texto$,$texto$Caso anual completo confirmado el 13/10/2026.$texto$,$texto$No cancelar el pago ni aplicar descuentos manuales para cerrar el ejercicio. Devoluciones del otro acuerdo de $1,400.00 y pruebas de duplicados/dos pestañas siguen pendientes.$texto$,$texto$/admin/catalogos/cargos$texto$),
('pago-anual-diciembre-bonificado',12,$texto$Consultar quién tiene un año completo liquidado$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Filtros y Excel$texto$,$texto$1. Como consulta complementaria entra a Administración → Finanzas → Pagos recibidos; en Tipo de cobertura selecciona Año completo — liquidado y en Año cubierto captura 2027; 2. Si conservas filtros de fechas del pago, revisa que incluyan su fecha real; para localizar un pago de 2026 que cubre 2027 deja esas fechas vacías o incluye 2026; Pulsa Aplicar filtros. 3. Identifica el folio y la columna Cobertura por alumno / año; abre Ver → Cobertura anual para conocer alumno, concepto, doce meses y estado. No basta sumar doce cargos de distintos hermanos o conceptos. 4. Pulsa Exportar Excel si necesitas el reporte: conserva los mismos filtros y las columnas de cobertura y beneficio pactado. Este paso es una consulta adicional disponible, no una nueva captura financiera ni una prueba humana adicional que se dé por realizada.$texto$,$texto$Fecha del pago 2026 y Año cubierto 2027 son criterios distintos; el año cubierto no está fijo.$texto$,$texto$Reporte filtrado y paginado de cobertura anual.$texto$,$texto$La etiqueta se calcula con abonos vigentes y condiciones del acuerdo; pendiente, cancelado o no liquidado no equivalen a un año completo pagado.$texto$,$texto$/admin/catalogos/pagos$texto$)
) v(slug,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta) ON g.slug=v.slug;
